"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[4201],{44201:e=>{e.exports=JSON.parse('{"schemaVersion":1,"locale":"en","slug":"servisy","title":"Directory. Services and sources: Where to act and where the figures come from","sourceFingerprint":"83e2fdb5cf8885645e4bcc0055fa063b6156b896cb268680c59ad75b1f280d70","blocks":[{"id":"b001","markdown":"## Services and sources"},{"id":"b002","markdown":"Where to act and where the figures come from, in one place"},{"id":"b003","markdown":"Every lesson’s sites and sources on one page: where to perform the suggested actions and where the figures originate. Use these links or bookmarks rather than search adverts, because fake sites are common."},{"id":"b004","markdown":"### Where to act"},{"id":"b005","markdown":"Use these for the lessons’ actions: credit restrictions, credit history and deductions."},{"id":"b006","markdown":"- Gosuslugi gosuslugi.ru: credit history, credit and SIM restrictions, police reports and deductions. Also enable confirmed sign-in. Lesson 4.\\n- Taxpayer account lkfl2.nalog.ru: prefilled deduction applications and 3-NDFL returns. Sign in through Gosuslugi. Lesson 10.\\n- Social Fund sfr.gov.ru: family tax payment applications, also available through Gosuslugi. Lesson 10.\\n- DIA asv.org.ru: Deposit Insurance Agency member-bank list. Check eligibility and the 1.4 million RUB per-person per-bank limit. Lesson 6."},{"id":"b007","markdown":"### Where the figures come from"},{"id":"b008","markdown":"Rates and laws change. Check current information at the primary source."},{"id":"b009","markdown":"- Bank of Russia cbr.ru: key rate, average maximum deposit rate among the 10 largest banks, debt burden, fraud statistics and analyst forecasts. Lesson 9.\\n- Rosstat rosstat.gov.ru: inflation and average salary used in lesson examples. Lesson 8.\\n- Federal Tax Service nalog.gov.ru: personal income tax rates, deductions and caps. Lesson 10.\\n- United Credit Bureau bki-okb.ru: average full borrowing costs, including credit cards. Lesson 4.\\n- Russian Field russianfield.com: survey of savings availability and months of runway. Lesson 1.\\n- NAFI nafi.ru: analytical centre estimating the share without savings together with the Finance Ministry’s NIFI. Lesson 1.\\n- Finance Ministry NIFI nifi.ru: Financial Research Institute, another source estimating households without savings. Lesson 1."},{"id":"b010","markdown":"### Additional official service"},{"id":"b011","markdown":"The Bank of Russia’s Central Catalogue of Credit Histories identifies which bureaus hold your credit history. Check through the official service; never enter personal data into advertising copies."},{"id":"b012","markdown":"Banks are not advertised here. Choose them using lesson 9’s rules rather than an affiliate link."}],"terms":[],"quizzes":[],"officialSources":[{"id":"gosuslugi","title":"Gosuslugi","url":"https://www.gosuslugi.ru/","description":"Credit history, credit and SIM-card restrictions, applications and secure sign-in."},{"id":"tax-cabinet","title":"Taxpayer account","url":"https://lkfl2.nalog.ru/","description":"Prefilled deduction applications and 3-NDFL tax returns; sign in through Gosuslugi."},{"id":"social-fund","title":"Social Fund of Russia","url":"https://sfr.gov.ru/","description":"Family tax payment eligibility and applications."},{"id":"deposit-insurance","title":"Deposit Insurance Agency","url":"https://www.asv.org.ru/","description":"Check bank membership, deposit coverage and compensation conditions."},{"id":"central-bank","title":"Bank of Russia","url":"https://www.cbr.ru/","description":"Key rate, deposit-rate monitoring, debt burden and fraud protection."},{"id":"rosstat","title":"Rosstat","url":"https://rosstat.gov.ru/","description":"Official inflation, price and accrued-wage statistics."},{"id":"tax-service","title":"Federal Tax Service","url":"https://www.nalog.gov.ru/","description":"Current personal income tax rates, deduction categories, caps and documentary requirements."},{"id":"credit-bureau","title":"United Credit Bureau","url":"https://bki-okb.ru/","description":"Credit history and the bureau’s primary full-cost-of-credit data."},{"id":"russian-field","title":"Russian Field","url":"https://russianfield.com/","description":"Primary survey source on savings and financial runway; a research organisation, not a state regulator."},{"id":"nafi","title":"NAFI Analytical Centre","url":"https://nafi.ru/","description":"Primary research into financial behaviour and savings; an analytical centre, not a state regulator."},{"id":"nifi","title":"Financial Research Institute","url":"https://www.nifi.ru/","description":"Financial-literacy and savings research; check survey dates and methodology."},{"id":"credit-catalogue","title":"Central Catalogue of Credit Histories","url":"https://www.cbr.ru/ckki/","description":"Official Bank of Russia service identifying bureaus holding your credit history."}]}')}}]);